# Broadcast index helper: dims are supplied innermost-first, at most 8 of them.
# ---------------------------------------------------------------------------


@triton.jit
def _kl_div_advance(idx, aoff, boff, z, sa, sb):
    coord = idx % z
    idx = idx // z
    aoff += coord * sa
    boff += coord * sb
    return idx, aoff, boff


