    t = tl.load(tgt_ptr + offs, mask=mask, other=0.0).to(tl.float32)
    if log_target:
        loss = tl.exp(t) * (t - s)
    else:
        xlogy = tl.where(t == 0.0, 0.0, t * tl.log(t))
        loss = xlogy - t * s
    tl.store(out_ptr + offs, loss.to(out_ptr.dtype.element_ty), mask=mask)


