    nprog = tl.num_programs(0)
    acc = tl.zeros((BLOCK_SIZE,), dtype=tl.float32)
    for start in range(pid * BLOCK_SIZE, n_elements, nprog * BLOCK_SIZE):
        offs = start + tl.arange(0, BLOCK_SIZE)
        mask = offs < n_elements
        s = tl.load(inp_ptr + offs, mask=mask, other=0.0)
        t = tl.load(tgt_ptr + offs, mask=mask, other=0.0)
        if log_target:
            s32 = s.to(tl.float32)
            t32 = t.to(tl.float32)
            loss = tl.exp(t32) * (t32 - s32)
