# ---------------------------------------------------------------------------
# Host wrapper
# ---------------------------------------------------------------------------


def _norm_reduction(reduction):
    """Map python/torch reduction spellings onto ATen semantics.

    ATen Reduction: None=0 (elementwise), Mean=1, Sum=2, BatchMean=3 which the
    ATen kernel returns as the plain sum (F.kl_div divides separately).
    """
    batchmean = False
    if isinstance(reduction, str):
        r = reduction.lower()
        if r == "none":
            red = 0
        elif r == "mean":
            red = 1
        elif r == "sum":
            red = 2
        elif r == "batchmean":
            red = 2
            batchmean = True
        else:
            raise ValueError("kl_div: unsupported reduction %r" % (reduction,))
    elif reduction is None:
        red = 0
    else:
        red = int(reduction)
        if red == 1:
            red = 1
        elif red == 0:
            red = 0
        else:
            red = 2
    return red, batchmean


_MAX_DIMS = 8


def _bcast_params(a, b, bshape):
    """Return (sizes, a_strides, b_strides) innermost-first, padded to 8 dims."""
    nd = len(bshape)
    pad_a = nd - a.dim()
    pad_b = nd - b.dim()
    ash = (1,) * pad_a + tuple(int(x) for x in a.shape)
    bsh = (1,) * pad_b + tuple(int(x) for x in b.shape)
    astr = (0,) * pad_a + tuple(int(x) for x in a.stride())
    bstr = (0,) * pad_b + tuple(int(x) for x in b.stride())
    dims = []
    for d in range(nd):
        z = int(bshape[d])
        dims.append(
            [
                z,
                astr[d] if ash[d] == z else 0,
                bstr[d] if bsh[d] == z else 0,
            ]
        )
    while len(dims) > _MAX_DIMS:
        outer = dims[0]
        inner = dims[1]
        if inner[0] == 1:
            dims = [outer] + dims[2:]
            continue
        if outer[0] == 1:
            dims = [inner] + dims[2:]
            continue
        for t in (1, 2):
            if outer[t] == 0 or inner[t] == 0:
                raise ValueError("kl_div: cannot collapse broadcast dimensions")
            if outer[t] != inner[0] * inner[t]:
                raise ValueError("kl_div: cannot collapse broadcast dimensions")
        dims = [[outer[0] * inner[0], inner[1], inner[2]]] + dims[2:]
    rev = list(reversed(dims))
    while len(rev) > 1 and rev[-1][0] == 1:
        rev.pop()
    sizes = [d[0] for d in rev]
    sstr = [d[1] for d in rev]
    tstr = [d[2] for d in rev]
    nd_used = len(sizes)
    while len(sizes) < _MAX_DIMS:
        sizes.append(1)
        sstr.append(0)
        tstr.append(0)
    return tuple(sizes), tuple(sstr), tuple(tstr), nd_used


def _flat_pair(a, b):
    return a.shape == b.shape and a.is_contiguous() and b.is_contiguous()


_ELEM_BLOCK = 1024
_RED_BLOCK = 1024
_RED_BLOCK_BIG = 4096
_RED_BIG_MIN = 4096
_PART_BLOCK = 4096
_SINGLE_MAX = 32768
_PROG_CAP = 128

_VC_CACHE = {}


def _vector_cores():
    """Read-only query of the device's vector-core count (never hardcoded).

    A reduce program is pure vector work, so the stage-1 grid is sized to the
    device's own vector-core count when the target exposes it; otherwise the
    previous fixed program cap is kept.
    """
    key = "vc"
    cached = _VC_CACHE.get(key)
    if cached:
        return cached
    n = 0
    try:
        props = torch.npu.get_device_properties(torch.npu.current_device())
        n = int(getattr(props, "vector_core_num", 0) or 0)
    except Exception:
        n = 0
    if n <= 0:
        try:
            from triton.runtime import driver

            utils = driver.active.utils
            fn = getattr(utils, "get_aivector_core_num", None)
            if fn is not None:
                n = int(fn())
            else:
                n = int(utils.get_device_properties(0)["num_vectorcore"])
        except Exception:
            n = 0
    if n <= 0:
        n = _PROG_CAP
    _VC_CACHE[key] = n
    return n


def kl_div(self, target, reduction=1, log_target=False):
    inp = self
    red, batchmean = _norm_reduction(reduction)
    lt = bool(log_target)
    out_dtype = torch.promote_types(inp.dtype, target.dtype)
    device = inp.device

    bshape = torch.broadcast_shapes(tuple(inp.shape), tuple(target.shape))
    n = 1
    for s in bshape:
        n *= int(s)

    if red == 0:
        out = torch.empty(bshape, dtype=out_dtype, device=device)
        if n == 0:
            return out
        grid = (triton.cdiv(n, _ELEM_BLOCK),)
        if _flat_pair(inp, target):
            _kl_div_elem_kernel[grid](
                inp,
                target,
                out,
                n,
                log_target=lt,
                BLOCK_SIZE=_ELEM_BLOCK,
            )
        else:
            sizes, sstr, tstr, nd = _bcast_params(inp, target, bshape)
            _kl_div_bcast_elem_kernel[grid](
                inp,
                target,
                out,
                n,
                *sizes,
                *sstr,
                *tstr,
                NDIM=nd,
                log_target=lt,
                BLOCK_SIZE=_ELEM_BLOCK,
            )
        return out

    out = torch.empty((), dtype=out_dtype, device=device)
    if n == 0:
        fill = float("nan") if red == 1 else 0.0
        _kl_div_fill_kernel[(1,)](out, fill)
        return out

    divide = red == 1 or batchmean
    if batchmean:
        denom = float(inp.shape[0]) if inp.dim() > 0 else 1.0
    else:
        denom = float(n)

    nblocks = triton.cdiv(n, _PART_BLOCK)
    nv = _vector_cores()
    half = (inp.dtype == target.dtype) and (inp.dtype == torch.float16)
    if _flat_pair(inp, target):
        if n <= _SINGLE_MAX:
            _kl_div_reduce_single_kernel[(1,)](
                inp,
                target,
                out,
                n,
                denom,
                log_target=lt,
                HALF=half,
                divide=divide,
                BLOCK_SIZE=(_RED_BLOCK_BIG if n >= _RED_BIG_MIN else _RED_BLOCK),
            )
            return out
        nprog = min(nblocks, nv)
        part = torch.empty((nprog,), dtype=torch.float32, device=device)
        _kl_div_partial_kernel[(nprog,)](
            inp,
            target,
            part,
            n,
            log_target=lt,
            HALF=half,
            BLOCK_SIZE=_PART_BLOCK,
        )
    else:
        sizes, sstr, tstr, nd = _bcast_params(inp, target, bshape)
        nprog = min(nblocks, nv)
        part = torch.empty((nprog,), dtype=torch.float32, device=device)
        _kl_div_bcast_partial_kernel[(nprog,)](
            inp,
            target,
            part,
            n,
            *sizes,
            *sstr,
            *tstr,
            NDIM=nd,
            log_target=lt,
            HALF=half,
            BLOCK_SIZE=_PART_BLOCK,
        )
    block_p = min(triton.next_power_of_2(nprog), 4096)
    _kl_div_final_kernel[(1,)](
        part,
        out,
        nprog,
        denom,
        divide=divide,
        BLOCK_P=block_p,
    )
    return out
